41	FMK_FUNC_HOST_VISIBILITY std::shared_ptr<OpParserFactory> OpParserFactory::Instance(
42	    const domi::FrameworkType framework) {
43	  // Each framework corresponds to one op parser factory,
44	  // If instances are static data members of opparserfactory, the order of their construction is uncertain.
45	  // Instances cannot be a member of a class because they may be used before initialization, resulting in a run error.
46	  static std::map<domi::FrameworkType, std::shared_ptr<OpParserFactory>> instances;
