86	// and does not involve concurrency, so there is no need to lock it
87	FMK_FUNC_HOST_VISIBILITY void OpParserFactory::RegisterCreator(const std::string &type, CREATOR_FUN fun,
88	                                                               bool is_fusion_op) {
89	  std::map<std::string, CREATOR_FUN> *op_parser_creator_map = &op_parser_creator_map_;
90	  if (is_fusion_op) {
91	    op_parser_creator_map = &fusion_op_parser_creator_map_;
92	  }
93	
94	  GELOGD("OpParserFactory::RegisterCreator: op type:%s, is_fusion_op:%d.", type.c_str(), is_fusion_op);
