275	domi::Status AclGraphParserUtil::ParseAclOutputNodes(const string &out_nodes) const {
276	  try {
277	    ge::GetParserContext().out_nodes_map.clear();
278	    ge::GetParserContext().user_out_nodes.clear();
279	    ge::GetParserContext().user_out_tensors.clear();
280	    ge::GetParserContext().default_out_nodes.clear();
281	    // parse output node
282	    if (!out_nodes.empty()) {
283	      uint32_t set_output_mode = 0;
284	
285	      vector<string> nodes_v = StringUtils::Split(out_nodes, ';');
286	      for (const string &node : nodes_v) {
287	        vector<string> key_value_v = StringUtils::Split(node, ':');
288	        if (key_value_v.size() != 2) {  // The size must be 2.
289	          if (key_value_v.size() == 1 && kSupportTensorAsOutput.count(ge::GetParserContext().type) > 0) {
290	            set_output_mode |= kSetOutputWithTensorName;
291	            if (set_output_mode == kSetOutputModeMixed) {
292	              break;
293	            }
294	            ge::GetParserContext().user_out_tensors.push_back(node);
295	            continue;
296	          }
297	          REPORT_PREDEFINED_ERR_MSG(
298	              "E10001", std::vector<const char *>({"parameter", "value", "reason"}),
299	              std::vector<const char *>(
300	                  {"out_nodes", node.c_str(), "The correct format is \"node_name1:0; node_name1:1; node_name2:0\"."}));
301	          GELOGE(PARAM_INVALID,
302	                 "[Check][Param] The input format of out_nodes is invalid, the correct format is "
303	                 "\"node_name1:0; node_name1:1; node_name2:0\", while the actual input is %s.",
304	                 node.c_str());
305	          return PARAM_INVALID;
306	        }
307	        set_output_mode |= kSetOutputWithNodeAndIndex;
308	        if (set_output_mode == kSetOutputModeMixed) {
309	          break;
310	        }
311	        // stoi: The method may throw an exception: invalid_argument/out_of_range
312	        if (!CheckDigitStr(key_value_v[1])) {
313	          REPORT_PREDEFINED_ERR_MSG(
314	              "E10001", std::vector<const char *>({"parameter", "value", "reason"}),
315	              std::vector<const char *>({"out_nodes", out_nodes.c_str(), "It is not a positive integer."}));
316	          GELOGE(PARAM_INVALID, "[Check][Param] This str:%s must be digit string, while the actual input is %s",
317	                 key_value_v[1].c_str(), out_nodes.c_str());
318	          return PARAM_INVALID;
319	        }
320	
321	        auto iter = ge::GetParserContext().out_nodes_map.find(key_value_v[0]);
322	        int32_t index = stoi(StringUtils::Trim(key_value_v[1]));
323	        GELOGD("Get output info: node[%s] and index[%d]", key_value_v[0].c_str(), index);
324	        if (iter != ge::GetParserContext().out_nodes_map.end()) {
325	          iter->second.emplace_back(index);
326	        } else {
327	          std::vector<int32_t> index_v;
328	          index_v.emplace_back(index);
329	          ge::GetParserContext().out_nodes_map.emplace(key_value_v[0], index_v);
330	        }
331	        ge::GetParserContext().user_out_nodes.emplace_back(key_value_v[0], index);
332	      }
333	      if (set_output_mode == kSetOutputModeMixed) {
334	        REPORT_PREDEFINED_ERR_MSG(
335	            "E10001", std::vector<const char *>({"parameter", "value", "reason"}),
336	            std::vector<const char *>(
337	                {"--out_nodes", out_nodes.c_str(), "Only one of index, top_name and output_name can be used."}));
338	        GELOGE(PARAM_INVALID,
339	               "[Parse][Param]This out_nodes str must be all index or tensor_name, "
340	               "while the actual input is %s",
341	               out_nodes.c_str());
342	        return PARAM_INVALID;
343	      }
344	    }
345	  } catch (std::invalid_argument &) {
346	    GELOGE(PARAM_INVALID, "[Check][Param] Invalid of out_nodes: %s ", out_nodes.c_str());
347	    REPORT_PREDEFINED_ERR_MSG("E10014", std::vector<const char *>({"parameter", "value"}),
348	                              std::vector<const char *>({"out_nodes", out_nodes.c_str()}));
349	    return PARAM_INVALID;
350	  } catch (std::out_of_range &) {
351	    GELOGE(PARAM_INVALID, "[Check][Param] Invalid of out_nodes: %s ", out_nodes.c_str());
352	    REPORT_PREDEFINED_ERR_MSG("E10013", std::vector<const char *>({"parameter", "value"}),
353	                              std::vector<const char *>({"out_nodes", out_nodes.c_str()}));
354	    return PARAM_INVALID;
355	  }
356	  return SUCCESS;
357	}
