359	domi::Status AclGraphParserUtil::ParseAclOutputFp16NodesFormat(const string &is_output_fp16) const {
360	  if (is_output_fp16.empty()) {
361	    return SUCCESS;
362	  }
363	
364	  vector<domiTensorFormat_t> &output_formats = ge::GetParserContext().output_formats;
365	  output_formats.clear();
366	  vector<string> node_format_vec = StringUtils::Split(is_output_fp16, ',');
367	  for (auto &is_fp16 : node_format_vec) {
368	    StringUtils::Trim(is_fp16);
369	    if (!CheckInputTrueOrFalse(is_fp16, "is_output_adjust_hw_layout")) {
370	      GELOGE(PARAM_INVALID,
