406	domi::Status AclGraphParserUtil::ParseAclInputFp16Nodes(const ComputeGraphPtr &graph, const string &input_fp16_nodes,
407	                                                        const string &is_input_adjust_hw_layout) const {
408	  GE_CHECK_NOTNULL(graph);
409	  vector<string> adjust_fp16_format_vec;
410	  if (!is_input_adjust_hw_layout.empty()) {
411	    adjust_fp16_format_vec = StringUtils::Split(is_input_adjust_hw_layout, ',');
412	    for (auto &s : adjust_fp16_format_vec) {
413	      StringUtils::Trim(s);
414	      if (!CheckInputTrueOrFalse(s, "is_input_adjust_hw_layout")) {
415	        GELOGE(PARAM_INVALID,
416	               "[Check][Param] Invalid Param, is_input_adjust_hw_layout "
417	               "only support true/false: but is [%s]",
418	               is_input_adjust_hw_layout.c_str());
419	        return PARAM_INVALID;
420	      }
421	    }
422	  }
423	  if (input_fp16_nodes.empty()) {
424	    return SUCCESS;
425	  }
426	  GELOGI("The input_fp16_nodes is set %s", input_fp16_nodes.c_str());
427	  vector<string> input_fp16_nodes_vec = StringUtils::Split(input_fp16_nodes, ';');
428	  for (size_t i = 0; i < input_fp16_nodes_vec.size(); ++i) {
429	    ge::NodePtr node = graph->FindNode(input_fp16_nodes_vec[i]);
430	    if (node == nullptr) {
431	      REPORT_PREDEFINED_ERR_MSG("E10016", std::vector<const char *>({"parameter", "opname"}),
432	                                std::vector<const char *>({"input_fp16_nodes", input_fp16_nodes_vec[i].c_str()}));
433	      GELOGE(PARAM_INVALID, "[Check][Param] Input parameter[input_fp16_nodes]'s opname[%s] does not exist in model",
434	             input_fp16_nodes_vec[i].c_str());
435	      return PARAM_INVALID;
436	    }
437	    auto op_desc = node->GetOpDesc();
438	    GE_CHECK_NOTNULL(op_desc);
439	    if (op_desc->GetType() != ge::parser::DATA) {
440	      REPORT_PREDEFINED_ERR_MSG("E10017", std::vector<const char *>({"parameter", "opname"}),
441	                                std::vector<const char *>({"input_fp16_nodes", input_fp16_nodes_vec[i].c_str()}));
442	      GELOGE(PARAM_INVALID, "[Check][Param] Input parameter[input_fp16_nodes]'s opname[%s] is not a input opname",
443	             input_fp16_nodes_vec[i].c_str());
444	      return PARAM_INVALID;
445	    }
446	    AddAttrsForInputNodes(adjust_fp16_format_vec, input_fp16_nodes_vec[i], i, op_desc);
447	  }
448	  return SUCCESS;
449	}
