451	domi::Status AclGraphParserUtil::SetSpecifyIndexAttrByInputNames(const ComputeGraphPtr &graph,
452	                                                                 const std::string &input_data_names) const {
453	  std::vector<std::string> input_names = StringUtils::Split(input_data_names, ',');
454	  std::unordered_map<std::string, size_t> name_to_index;
455	  for (auto &input_name : input_names) {
456	    if (!name_to_index.emplace(input_name, name_to_index.size()).second) {
457	      GELOGE(PARAM_INVALID, "[Check][Param] Duplicate input name[%s].", input_name.c_str());
458	      return FAILED;
459	    }
460	  }
461	
462	  for (const NodePtr &node : graph->GetDirectNode()) {
463	    if (node->GetType() != ge::parser::DATA) {
464	      continue;
465	    }
466	    auto op_desc = node->GetOpDesc();
467	    GE_CHECK_NOTNULL(op_desc);
468	    auto iter = name_to_index.find(node->GetName());
469	    if (iter == name_to_index.cend()) {
470	      GELOGE(PARAM_INVALID, "[Check][Param] Input name[%s] is not in input_data_names", node->GetName().c_str());
471	      return FAILED;
472	    }
473	    GELOGI("[SetSpecifyIndexAttr] set node(%s) index attr, index is %ld", op_desc->GetName().c_str(), iter->second);
474	    if (!AttrUtils::SetInt(op_desc, ATTR_NAME_INDEX, iter->second)) {
475	      REPORT_INNER_ERR_MSG("E19999", "set attr %s failed for node:%s", ATTR_NAME_INDEX.c_str(),
476	                           op_desc->GetName().c_str());
477	      GELOGE(FAILED, "set attr %s failed for node:%s", ATTR_NAME_INDEX.c_str(), op_desc->GetName().c_str());
478	      return FAILED;
479	    }
480	  }
481	  return SUCCESS;
482	}
