484	void AclGraphParserUtil::CreateOutputNodesInfo(std::vector<std::pair<ge::NodePtr, int32_t>> &output_nodes_info,
485	                                               std::vector<std::string> &output_nodes_name) const {
486	  output_nodes_name.clear();
487	  auto &out_tensor_names = ge::GetParserContext().out_tensor_names;
488	  if (out_tensor_names.empty()) {
489	    // tf process, no top name.
490	    for (const auto &output_node_info : output_nodes_info) {
491	      std::string node_name = output_node_info.first->GetName();
492	      int32_t index = output_node_info.second;
493	      output_nodes_name.push_back(node_name + ":" + std::to_string(index));
494	    }
495	    return;
496	  }
497	
498	  // Need add top name after node_name:index
499	  for (size_t i = 0; i < output_nodes_info.size(); ++i) {
500	    auto node = output_nodes_info[i].first;
501	    int32_t index = output_nodes_info[i].second;
502	    std::string node_name = node->GetName();
503	    if (i < out_tensor_names.size()) {
504	      auto output_desc = node->GetOpDesc()->MutableOutputDesc(static_cast<uint32_t>(index));
505	      (void)AttrUtils::SetStr(output_desc, ATTR_NAME_ORIGIN_OUTPUT_TENSOR_NAME, out_tensor_names[i]);
506	      std::string output_name = node->GetName() + ":" + std::to_string(index) + ":" + out_tensor_names[i];
507	      output_nodes_name.push_back(output_name);
508	      GELOGD("Output[%zu] name[%s]", i, output_name.c_str());
509	    } else {
510	      GELOGW("Get top name of node [%s] fail.", node_name.c_str());
511	      output_nodes_name.push_back(node_name + ":" + std::to_string(index));
512	    }
513	  }
514	}
