516	domi::Status AclGraphParserUtil::GetOutputLeaf(NodePtr node,
517	                                               std::vector<std::pair<ge::NodePtr, int32_t>> &output_nodes_info) const {
518	  ge::OpDescPtr tmpDescPtr = node->GetOpDesc();
519	  if (tmpDescPtr == nullptr) {
520	    REPORT_INNER_ERR_MSG("E19999", "param node has no opdesc.");
521	    GELOGE(domi::FAILED, "[Get][OpDesc] param node has no opdesc.");
522	    return domi::FAILED;
523	  }
524	  size_t size = tmpDescPtr->GetOutputsSize();
525	  if (node->GetType() != ge::parser::NETOUTPUT) {
526	    for (size_t index = 0; index < size; ++index) {
527	      output_nodes_info.push_back(std::make_pair(node, index));
528	      GELOGD("Get output leaf node:%s.", node->GetName().c_str());
529	    }
530	  } else {
531	    const auto in_anchors = node->GetAllInDataAnchors();
532	    for (auto in_anchor : in_anchors) {
533	      auto out_anchor = in_anchor->GetPeerOutAnchor();
534	      if (out_anchor == nullptr) {
535	        REPORT_INNER_ERR_MSG("E19999", "Get leaf node op desc fail.");
536	        GELOGE(domi::FAILED, "[Invoke][GetPeerOutAnchor] Get leaf node op desc fail.");
537	        return domi::FAILED;
538	      }
539	      auto out_node = out_anchor->GetOwnerNode();
540	      output_nodes_info.push_back(std::make_pair(out_node, out_anchor->GetIdx()));
541	    }
542	  }
543	  return SUCCESS;
544	}
