546	domi::Status AclGraphParserUtil::GetDefaultOutInfo(
547	    ge::ComputeGraphPtr &compute_graph, std::vector<std::pair<ge::NodePtr, int32_t>> &output_nodes_info) const {
548	  std::vector<std::pair<std::string, int32_t>> default_out_nodes = ge::GetParserContext().default_out_nodes;
549	  if (!default_out_nodes.empty()) {
