569	domi::Status AclGraphParserUtil::SetOutputNodeInfo(ge::Graph &graph,
570	                                                   const std::map<AscendString, AscendString> &parser_params) const {
571	  (void)parser_params;
572	  ge::ComputeGraphPtr compute_graph = ge::GraphUtilsEx::GetComputeGraph(graph);
573	  GE_CHECK_NOTNULL(compute_graph);
574	
575	  std::vector<std::pair<std::string, int32_t>> user_out_nodes = ge::GetParserContext().user_out_nodes;
576	  std::vector<domiTensorFormat_t> output_formats = ge::GetParserContext().output_formats;
577	  std::vector<std::pair<ge::NodePtr, int32_t>> output_nodes_info;
578	  std::vector<std::string> output_nodes_name;
579	
580	  // User declared outputs
581	  for (uint32_t i = 0; i < user_out_nodes.size(); ++i) {
582	    ge::NodePtr out_node = compute_graph->FindNode(user_out_nodes[i].first);
583	    if (out_node == nullptr) {
584	      REPORT_PREDEFINED_ERR_MSG("E10016", std::vector<const char *>({"parameter", "opname"}),
585	                                std::vector<const char *>({"out_nodes", user_out_nodes[i].first.c_str()}));
586	      GELOGE(domi::FAILED, "[Check][Param] Cannot find out_nodes(%d) (%s) in graph.", i,
587	             user_out_nodes[i].first.c_str());
588	      return domi::FAILED;
589	    }
590	    auto op_desc = out_node->GetOpDesc();
591	    GE_CHECK_NOTNULL(op_desc);
592	    if (CheckOutNode(op_desc, user_out_nodes[i].second) != SUCCESS) {
593	      GELOGE(domi::FAILED, "[CheckOut][Node] (%s) fail.", user_out_nodes[i].first.c_str());
594	      return domi::FAILED;
595	    }
596	
597	    // add user_define_output_nodes attr.
598	    (void)ge::AttrUtils::SetStr(op_desc, ATTR_ATC_USER_DEFINE_OUTPUT_NODES, "true");
599	
600	    if (i < output_formats.size()) {
601	      if (output_formats[i] == domi::DOMI_TENSOR_NC1HWC0) {
602	        GELOGI("The output node [%s] should be set NC1HWC0", user_out_nodes[i].first.c_str());
603	        vector<string> output_fp16_5hd_vec;
604	        (void)ge::AttrUtils::GetListStr(op_desc, "_user_defined_output_fp16_5hd", output_fp16_5hd_vec);
605	        output_fp16_5hd_vec.push_back(std::to_string(user_out_nodes[i].second) + ":" + "NC1HWC0");
606	        (void)ge::AttrUtils::SetListStr(op_desc, "_user_defined_output_fp16_5hd", output_fp16_5hd_vec);
607	      }
608	    }
609	    output_nodes_info.push_back(std::make_pair(out_node, user_out_nodes[i].second));
610	  }
611	  // default output node (leaf)
612	  if (user_out_nodes.empty()) {
613	    if (GetDefaultOutInfo(compute_graph, output_nodes_info) != SUCCESS) {
614	      GELOGE(domi::FAILED, "[Invoke][GetDefaultOutInfo] failed, graph:%s.", compute_graph->GetName().c_str());
615	      return domi::FAILED;
616	    }
617	  }
618	  CreateOutputNodesInfo(output_nodes_info, output_nodes_name);
619	  compute_graph->SetGraphOutNodesInfo(output_nodes_info);
620	  ge::GetParserContext().net_out_nodes = output_nodes_name;
621	  GELOGI("Set graph %s output node success.", compute_graph->GetName().c_str());
622	  return domi::SUCCESS;
623	}
