647	domi::Status AclGraphParserUtil::ParseParamsBeforeGraph(const std::map<AscendString, AscendString> &parser_params,
648	                                                        string &graph_name) const {
649	  GELOGI("Parse graph user options start.");
650	  ge::GetParserContext().input_nodes_format_map.clear();
651	  ge::GetParserContext().output_formats.clear();
652	  ge::GetParserContext().user_input_dims.clear();
653	  ge::GetParserContext().input_dims.clear();
654	  ge::GetParserContext().op_conf_map.clear();
655	  ge::GetParserContext().user_out_nodes.clear();
656	  ge::GetParserContext().default_out_nodes.clear();
657	  ge::GetParserContext().out_nodes_map.clear();
658	  ge::GetParserContext().user_out_tensors.clear();
659	  ge::GetParserContext().net_out_nodes.clear();
660	  ge::GetParserContext().out_tensor_names.clear();
661	  ge::GetParserContext().data_tensor_names.clear();
662	
663	  if (CheckOptions(parser_params) != SUCCESS) {
664	    GELOGE(FAILED, "[Check][Options] Parse paragrams invalid, graph:%s.", graph_name.c_str());
665	    return PARAM_INVALID;
666	  }
667	  // support paragrams: out_nodes, is_output_adjust_hw_layout, output, enable_scope_fusion_passes
668	  SetDefaultFormat();
669	
670	  string out_nodes;
671	  GetAclParams(parser_params, ge::ir_option::OUT_NODES, out_nodes);
672	  if (ParseAclOutputNodes(out_nodes) != SUCCESS) {
673	    GELOGE(FAILED, "[Invoke][ParseAclOutputNodes] Parse out_nodes failed, graph:%s.", graph_name.c_str());
674	    return PARAM_INVALID;
675	  }
676	
677	  string is_output_adjust_hw_layout;
678	  GetAclParams(parser_params, ge::ir_option::IS_OUTPUT_ADJUST_HW_LAYOUT, is_output_adjust_hw_layout);
679	  if (ParseAclOutputFp16NodesFormat(is_output_adjust_hw_layout) != SUCCESS) {
680	    GELOGE(FAILED, "[Invoke][ParseAclOutputFp16NodesFormat] Parse is_output_adjust_hw_layout failed, graph:%s.",
681	           graph_name.c_str());
682	    return PARAM_INVALID;
683	  }
684	
685	  string tmp_name;
686	  GetAclParams(parser_params, ge::ir_option::OUTPUT, tmp_name);
687	  graph_name =
688	      tmp_name.empty()
689	          ? (kGraphDefaultName + "_" + ge::parser::CurrentTimeInStr() + "_" + std::to_string(graph_name_index++))
690	          : tmp_name;
691	
692	  string enable_scope_fusion_passes;
693	  GetAclParams(parser_params, ge::ir_option::ENABLE_SCOPE_FUSION_PASSES, enable_scope_fusion_passes);
694	  if (ParseAclEnableScope(enable_scope_fusion_passes) != SUCCESS) {
695	    GELOGE(FAILED, "[Invoke][ParseAclEnableScope] Parse enable_scope_fusion_passes failed, graph:%s.",
696	           graph_name.c_str());
697	    return PARAM_INVALID;
698	  }
699	
700	  string input_dims;
701	  GetAclParams(parser_params, ge::ir_option::INPUT_SHAPE, input_dims);
702	  GE_ASSERT_SUCCESS(ParseAclInputShape(input_dims),
703	                    "[Invoke][ParseAclEnableScope] Parse enable_scope_fusion_passes failed, graph:%s.",
704	                    graph_name.c_str());
705	
706	  return SUCCESS;
707	}
