738	domi::Status AclGraphParserUtil::ParseAclInputShape(const string &input_shape) const {
739	  ge::GetParserContext().input_dims.clear();
740	  if (input_shape.empty()) {
741	    return SUCCESS;
742	  }
743	
744	  std::vector<std::string> shape_vec = StringUtils::Split(input_shape, ';');
745	  for (const auto &shape : shape_vec) {
746	    std::vector<std::string> shape_pair_vec = SplitInputShape(shape);
747	    if (shape_pair_vec.size() != kInputShapePairSize) {
748	      REPORT_PREDEFINED_ERR_MSG("E10002", std::vector<const char *>({"shape", "reason", "sample"}),
749	                                std::vector<const char *>({shape.c_str(), kSplitError1, kInputShapeSample1}));
750	      GELOGE(FAILED, "the parameter [--input_shape] Parse failed, value: \"%s\", reason: %s correct sample is %s.",
751	             shape.c_str(), kSplitError1, kInputShapeSample1);
752	      return FAILED;
753	    }
754	    // 支持设置成标量: []
755	    if (shape_pair_vec[1].empty()) {
756	      const auto node_name = StringUtils::Trim(shape_pair_vec[0]);
757	      ge::GetParserContext().input_dims.emplace(make_pair(node_name, std::vector<int64_t>{}));
758	      GELOGD("Input node name:%s, with shape:[]", node_name.c_str());
759	      continue;
760	    }
761	
762	    std::vector<std::string> shape_value_split = StringUtils::Split(shape_pair_vec[1], ',');
763	    std::vector<int64_t> shape_values;
764	    for (auto &shape_value_str : shape_value_split) {
765	      int64_t input_dim = 0;
766	      GE_ASSERT_TRUE(ConvertStringToNumber(StringUtils::Trim(shape_value_str), input_dim));
767	      shape_values.emplace_back(input_dim);
768	      GELOGD("Input node name:%s, with shape:%ld", StringUtils::Trim(shape_pair_vec[0]).c_str(), input_dim);
769	    }
770	    ge::GetParserContext().input_dims.emplace(make_pair(StringUtils::Trim(shape_pair_vec[0]), shape_values));
771	  }
772	  return SUCCESS;
773	}
