776	FMK_FUNC_HOST_VISIBILITY FMK_FUNC_DEV_VISIBILITY std::string RealPath(const char *path) {
777	  if (path == nullptr) {
778	    GELOGE(ge::FAILED, "path pointer is NULL.");
779	    return "";
780	  }
781	  if (strlen(path) >= PATH_MAX) {
782	    REPORT_PREDEFINED_ERR_MSG("E13002", std::vector<const char *>({"filepath", "size"}),
783	                              std::vector<const char *>({path, std::to_string(PATH_MAX).c_str()}));
784	    GELOGE(ge::FAILED, "[Check][Param] Path[%s] len is too long, it must be less than %d", path, PATH_MAX);
785	    return "";
786	  }
787	  // Nullptr is returned when the path does not exist or there is no permission
788	  // Return absolute path when path is accessible
789	  std::string res;
790	  char resolved_path[PATH_MAX] = {0};
791	  if (realpath(path, resolved_path) != nullptr) {
792	    res = resolved_path;
793	  }
794	
795	  return res;
796	}
