798	// Get file length
799	FMK_FUNC_HOST_VISIBILITY FMK_FUNC_DEV_VISIBILITY long GetFileLength(const std::string &input_file) {
800	  if (input_file.empty()) {
801	    REPORT_INNER_ERR_MSG("E19999", "input_file path is null, check invalid.");
802	    GELOGE(FAILED, "[Check][Param] input_file path is null.");
803	    return -1;
804	  }
805	
806	  std::string real_path = RealPath(input_file.c_str());
807	  char_t err_buf[kMaxErrStrLen + 1U] = {};
